package com.hiresense.controller;
import com.hiresense.dto.EmployeeDtos.*; import com.hiresense.service.EmployeeService; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/employees") @PreAuthorize("hasAnyRole('HR','ADMIN')") public class EmployeeController {private final EmployeeService s;public EmployeeController(EmployeeService x){s=x;} @GetMapping Page<EmployeeResponse> list(@RequestParam(required=false)String department,@RequestParam(required=false)Boolean attrition,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return s.list(department,attrition,page,size);} @GetMapping("/{id}") EmployeeResponse one(@PathVariable Long id){return s.map(s.get(id));} @PostMapping EmployeeResponse create(@Valid @RequestBody EmployeeRequest r){return s.create(r);} @PutMapping("/{id}") EmployeeResponse update(@PathVariable Long id,@Valid @RequestBody EmployeeRequest r){return s.update(id,r);} @DeleteMapping("/{id}") void delete(@PathVariable Long id){s.delete(id);} @PostMapping(value="/import",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) MapResponse importCsv(@RequestPart("file")MultipartFile f){return new MapResponse(s.importCsv(f));} public record MapResponse(int imported){} }
